func TestComputeHashEscapesOnlyQuoteBackslashAndControls(t *testing.T) {
	event := Event{
		Seq:        7,
		Account:    "a\"b\\c",
		Operation:  "line\nbreak\ttab",
		Resource:   "res<&>é",
		Result:     "ok",
		OccurredAt: "2026-10-05T00:00:00.5Z",
		PrevHash:   "abc123",
	}
	payload := `[7,"a\"b\\c","line\nbreak\ttab","res<&>é","ok","2026-10-05T00:00:00.5Z","abc123"]`
	want := hex.EncodeToString(sha256Bytes(payload))
	if got := computeHash(event); got != want {
